def test_AC2():
    """
    GIVEN: file scripts/lib/react_template.tpl has been modified by dev
    WHEN:  each of 6 per-site grep patterns is run against the file
    THEN:  all 7 per-site fail-patterns return 0 matches (any non-zero count means that site is still unpatched); AND grep for 'cover_image ||' in lines 860-1850 returns 6+ matches. Note: timeline entry has TWO patterns — guard (L1828) and src (L1830) — both must return 0.
    """
    # TODO(dev): replace the line below with the real test body. While the
    # TEST_INCOMPLETE sentinel is present the test will hard-fail, marking
